import {ScheduleStore} from './store.js';
import {cloudClient,cloudConfig,configureCloud,cloudEnabled,cloudUser} from './cloud.js';
import {dateKey} from './schedule.js';
import {coinTotal,normalize} from './development.js';
const $=s=>document.querySelector(s),store=new ScheduleStore();let state=null,busy=false;
function render(){if(!state)return;$('#steps-value').textContent=new Intl.NumberFormat('ru-RU').format(state.steps[dateKey()]||0);$('#steps-input').value=state.steps[dateKey()]||'';$('#useful-value').textContent=state.logs.filter(l=>l.date===dateKey()).reduce((n,l)=>n+l.minutes,0)+' мин';$('#coin-balance').textContent=coinTotal(state);}
try{state=normalize(await store.load());render();}catch(e){$('#home-status').textContent=e.message;}
$('#steps-form').addEventListener('submit',async e=>{e.preventDefault();if(!state||busy)return;busy=true;try{const next=structuredClone(state);next.steps[dateKey()]=Number($('#steps-input').value);state=normalize(await store.save(next));render();$('#home-status').textContent='Шаги сохранены';}catch(e){$('#home-status').textContent=e.message;}finally{busy=false;}});
$('#export-data').addEventListener('click',async()=>{try{const data=await new ScheduleStore().load();const url=URL.createObjectURL(new Blob([JSON.stringify({format:'dlife-backup-v1',exportedAt:new Date().toISOString(),state:data},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='dlife-'+dateKey()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){$('#home-status').textContent=e.message;}});
$('#open-cloud').addEventListener('click',()=>{const c=cloudConfig();$('#cloud-url').value=c?.url||'';$('#cloud-key').value=c?.key||'';$('#cloud-status').textContent=cloudEnabled()?'Хранилище: Supabase':'Хранилище: dLife. Переход выполняется только после успешного переноса.';$('#cloud-dialog').showModal();});
$('#cloud-config').addEventListener('submit',e=>{e.preventDefault();try{if(cloudEnabled())throw Error('Нельзя менять проект при активной синхронизации. Сначала сохрани резервную копию.');configureCloud($('#cloud-url').value,$('#cloud-key').value.trim());$('#cloud-status').textContent='Подключение сохранено. Войди в свой аккаунт.';}catch(e){$('#cloud-status').textContent=e.message;}});
$('#cloud-login').addEventListener('submit',async e=>{e.preventDefault();const c=cloudClient();if(!c)return $('#cloud-status').textContent='Сначала укажи проект.';const {error}=await c.auth.signInWithPassword({email:$('#cloud-email').value,password:$('#cloud-password').value});$('#cloud-password').value='';$('#cloud-status').textContent=error?error.message:'Вход выполнен. Можно подключить хранилище и капитал.';if(!error)capital();});
$('#cloud-migrate').addEventListener('click',async()=>{if(busy)return;busy=true;try{const user=await cloudUser();if(!user)throw Error('Сначала войди в Supabase.');const c=cloudClient();const {data,error}=await c.from('dlife_state').select('payload,revision').eq('user_id',user.id).maybeSingle();if(error)throw error;if(!data){const current=await new ScheduleStore().load();const result=await c.rpc('dlife_save',{p_payload:current,p_revision:0});if(result.error)throw result.error;}else if(!confirm('В Supabase уже есть данные. Подключить их? Текущие данные dLife останутся в прежнем хранилище.'))return;localStorage.setItem('dlife-cloud-enabled','true');location.reload();}catch(e){$('#cloud-status').textContent='Перенос не выполнен. Прежние данные сохранены. '+e.message;}finally{busy=false;}});
$('#cloud-logout').addEventListener('click',async()=>{await cloudClient()?.auth.signOut();$('#cloud-status').textContent='Выход выполнен. Для чтения данных Supabase войди снова.';});
async function capital(){const user=await cloudUser();if(!user)return;$('#capital-status').textContent='Загружаем кошельки dMoney…';try{const {data,error}=await cloudClient().from('wallets').select('balance,currency').eq('user_id',user.id);if(error)throw error;if(!data.length){$('#capital-value').textContent='0';$('#capital-status').textContent='В этом аккаунте нет кошельков dMoney';return;}const totals={};for(const w of data)totals[w.currency]=(totals[w.currency]||0)+Number(w.balance||0);$('#capital-value').textContent=Object.entries(totals).map(([c,v])=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:2}).format(v)+' '+c).join(' · ');$('#capital-status').textContent='dMoney · сумма кошельков по валютам';}catch(e){$('#capital-status').textContent='Не удалось прочитать dMoney: '+e.message;}}
$('#capital-refresh').addEventListener('click',capital);capital();
